def audio(clip):
 if clip not in cache:
  x,sr=sf.read(H/'input'/f'{clip}.wav');cache[clip]=(x.mean(axis=1) if x.ndim>1 else x,sr)
 return cache[clip]
def panel(row,fig,axs):
 t=row['GT_onset']; ids=row['associated_BP_ids'].split(';') if row['associated_BP_ids'] else [];rs=[records[k] for k in ids];start=min([t-.20]+[r['search_start_s'] for r in rs]);end=max([t+.20]+[r['search_end_s'] for r in rs]);x,sr=audio(row['clip_id']);lo=max(0,int((start-.03)*sr)//44*44);hi=min(len(x),int((end+.03)*sr));tx=np.arange(lo,hi)/sr;axs[0].plot((tx-t)*1000,x[lo:hi],color='.35',lw=.5)
 f,ts,z=stft(x[lo:hi],fs=sr,window='hann',nperseg=1024,noverlap=980,boundary=None,padded=False);a=abs(z);band=(f>=30)&(f<250);v=np.maximum(0,np.diff(a[band],axis=1,prepend=a[band,:1])).sum(axis=0);times=ts+lo/sr;axs[1].plot((times-t)*1000,v,color='.35',lw=.8)
 for ax in axs:
  ax.axvspan((row['GT_lower']-t)*1000,(row['GT_upper']-t)*1000,color='green',alpha=.2);ax.axvline(0,color='green',lw=1.2);ax.set_xlim((start-t)*1000,(end-t)*1000)
 for j,r in enumerate(rs):
  p=pred[r['BP']['native_note_id']];bp=r['BP']['onset_local_s'];cs=r['candidates'];ct=np.array([c['time_s'] for c in cs]);vs=np.array([c['flux'] for c in cs]);axs[1].scatter((ct-t)*1000,vs,s=9,color='.6');axs[1].axvline((bp-t)*1000,color='tab:orange',ls='--');axs[2].scatter((ct-t)*1000,p['probabilities'],s=10,label=r['BP']['native_note_id']);axs[2].axvline((bp-t)*1000,color='tab:orange',ls='--')
  if p['selected_s'] is not None:
   for ax in axs:ax.axvline((p['selected_s']-t)*1000,color='tab:blue',ls=':')
 axs[0].set_ylabel('Fishman amplitude');axs[1].set_ylabel('30–250 Hz flux');axs[2].set_ylabel('Model score');axs[2].axhline(rule['threshold'],color='.5',ls='--');axs[2].set_xlabel('ms relative to Fishman human GT');axs[2].legend(fontsize=7,loc='upper right');fig.suptitle(f"{row['GT_ID']} · {row['string']} / {row['condition']}\n{row['BP_association']} · {row['selector_status']} · error {row['signed_error_ms'] if row['signed_error_ms'] is not None else 'unresolved'} ms\nGreen: GT/interval · orange: native BP · blue dotted: frozen per-BP selection\nFor ambiguous BP correspondence, per-hypothesis decisions remain hypotheses, not GT matches.",fontsize=10)
with PdfPages(W/'JGA_LEARNED_ATTACK_SELECTOR_HOLDOUT.pdf') as pdf:
 for i,row in enumerate(rows):
  fig,axs=plt.subplots(3,1,figsize=(12,8),sharex=True,layout='constrained');panel(row,fig,axs);pdf.savefig(fig)
  if row['string']=='E' and row['signed_error_ms'] is not None and row['largest_flux_error_ms']>30:fig.savefig(W/'HOLDOUT_PREVIEW.png',dpi=120)
  plt.close(fig)
