 for i,v in enumerate(vals,1):axs[0].scatter(i+np.linspace(-.1,.1,len(v)),v,s=10,alpha=.5)
 axs[0].axhline(0,color='black');axs[0].set_ylabel('Signed error (ms)');axs[1].axis('off');p=ev['pooled']['methods'];data=[[name,p[m]['N'],f"{p[m]['median_absolute_ms']:.3f}",f"{p[m]['P95_absolute_ms']:.3f}",f"{p[m]['maximum_absolute_ms']:.3f}",f"{p[m]['within_10_pct']:.1f}%",f"{p[m]['useful_yield_10_pct']:.1f}%"] for name,m in zip(names,methods)];axs[1].table(cellText=data,colLabels=['Method','N','Med abs ms','P95 abs ms','Max abs ms','Within10','Yield /40GT'],loc='center',cellLoc='center');fig.suptitle('Locked holdout comparison — identical 35 resolved BP↔GT notes\nFive BP ambiguities remain unresolved; no timing correction. All outliers shown.');pdf.savefig(fig);plt.close(fig)
